class Reassembler:
    def __init__(self):
        self.buffer = b''
        self.state = 'sync1'  # states: sync1, sync2, length, payload, check
        self.length = 0
        self.payload = b''
        self.need = 0

    def feed(self, chunk: bytes) -> list[bytes]:
        self.buffer += chunk
        frames = []
        i = 0
        n = len(self.buffer)

        while i < n:
            if self.state == 'sync1':
                if self.buffer[i] == 0xAA:
                    self.state = 'sync2'
                i += 1
            elif self.state == 'sync2':
                if self.buffer[i] == 0x55:
                    self.state = 'length'
                    self.length_bytes = b''
                    self.need = 2
                else:
                    self.state = 'sync1'
                    # do not consume this byte, it might be 0xAA
                    continue
                i += 1
            elif self.state == 'length':
                take = min(self.need, n - i)
                self.length_bytes += self.buffer[i:i+take]
                i += take
                self.need -= take
                if self.need == 0:
                    self.length = int.from_bytes(self.length_bytes, 'little')
                    if self.length > 4096:
                        self.state = 'sync1'
                        self.length_bytes = b''
                        self.length = 0
                    else:
                        self.state = 'payload'
                        self.payload = b''
                        self.need = self.length
            elif self.state == 'payload':
                take = min(self.need, n - i)
                self.payload += self.buffer[i:i+take]
                i += take
                self.need -= take
                if self.need == 0:
                    self.state = 'check'
                    self.need = 1
            elif self.state == 'check':
                if i < n:
                    check = self.buffer[i]
                    i += 1
                    if len(self.payload) == 0:
                        expected = 0
                    else:
                        expected = 0
                        for b in self.payload:
                            expected ^= b
                    if check == expected:
                        frames.append(self.payload)
                    self.state = 'sync1'
                    self.payload = b''
                    self.length = 0
                    self.need = 0
                else:
                    break

        # Keep only the unprocessed part of the buffer
        self.buffer = self.buffer[i:]
        return frames
